INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李嗣源更名亶", "start_year": 927, "end_year": 927, "time_original": "927年正月癸丑朔", "dynasty": "五代十国", "description": "李嗣源更名亶。", "phases": [], "location_name": "后唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "68df9206-1320-5846-9bf9-e52f085c1c99"}, {"title": "孟知祥闻李严将来监军，拒绝奏请阻止的建议，派吏到绵剑迎候", "start_year": 927, "end_year": 927, "time_original": "927年正月本段；确日未载", "dynasty": "五代十国", "description": "孟知祥闻李严将来监军，拒绝奏请阻止的建议，派吏到绵剑迎候。", "phases": [], "location_name": "西川、绵州与剑州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c714f3f5-50e8-5d20-9d46-d7a6834ee24a"}, {"title": "武信节度使李绍文去世", "start_year": 927, "end_year": 927, "time_original": "927年正月本段；确日未载", "dynasty": "五代十国", "description": "武信节度使李绍文去世。", "phases": [], "location_name": "武信军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d5db8b43-927c-57f3-a5a7-9ec95d6a2ced"}, {"title": "孟知祥先任李敬周为遂州留后并催赴任，然后上表", "start_year": 927, "end_year": 927, "time_original": "927年正月壬戌", "dynasty": "五代十国", "description": "孟知祥先任李敬周为遂州留后并催赴任，然后上表。", "phases": [], "location_name": "成都至遂州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "93da3618-0610-5bfa-a1f7-ee063c640c04"}, {"title": "李严先遣使至成都，孟知祥向使者陈甲兵，期望李严惧而退回", "start_year": 927, "end_year": 927, "time_original": "927年正月本段；确日未载", "dynasty": "五代十国", "description": "李严先遣使至成都，孟知祥向使者陈甲兵，期望李严惧而退回。", "phases": [], "location_name": "成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3215f621-30ec-5a3b-b2a2-aed7ae4820a7"}, {"title": "安重诲认为孔循熟悉宫廷旧事与朝士才能，多听其言", "start_year": null, "end_year": null, "time_original": "927年正月置相议事所述背景，开始时间未载", "dynasty": "五代十国", "description": "安重诲认为孔循熟悉宫廷旧事与朝士才能，多听其言。", "phases": [], "location_name": "后唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bc162b50-caf1-5afb-bc37-d1c941a7db34"}, {"title": "孔循在豆卢革韦说获罪后的置相议中荐崔协，任圜主张李琪", "start_year": null, "end_year": null, "time_original": "豆卢革韦说获罪之后至927年正月任相前的议事，起日未载", "dynasty": "五代十国", "description": "孔循在豆卢革韦说获罪后的置相议中荐崔协，任圜主张李琪。", "phases": [], "location_name": "后唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "208fc898-9484-5219-828a-f34ebb9a5578"}, {"title": "郑珏素恶李琪，孔循向安重诲批评李琪不廉，力荐崔协", "start_year": null, "end_year": null, "time_original": "927年正月任相前议事，确日未载", "dynasty": "五代十国", "description": "郑珏素恶李琪，孔循向安重诲批评李琪不廉，力荐崔协。", "phases": [], "location_name": "后唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "03a8b773-c78b-508e-9325-38712239822a"}, {"title": "安重诲荐崔协，任圜当面反对；李嗣源认为冯道可以任相", "start_year": null, "end_year": null, "time_original": "927年正月任相前它日议事，确日未载", "dynasty": "五代十国", "description": "安重诲荐崔协，任圜当面反对；李嗣源认为冯道可以任相。", "phases": [], "location_name": "后唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "df04768c-8eda-5492-bd66-4a57de7fd73f"}, {"title": "孔循不揖而去，言任圜专断并坚持崔协任相，随后称疾不朝数日", "start_year": null, "end_year": null, "time_original": "议相之后、癸亥任相之前数日", "dynasty": "五代十国", "description": "孔循不揖而去，言任圜专断并坚持崔协任相，随后称疾不朝数日。", "phases": [], "location_name": "后唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5f59ed0d-f9e3-5c13-9950-ff9c7961b1d8"}, {"title": "安重诲私议让崔协暂备相位，任圜以苏合丸与蛣蜣比喻反对", "start_year": null, "end_year": null, "time_original": "927年正月任相前私议，确日未载", "dynasty": "五代十国", "description": "安重诲私议让崔协暂备相位，任圜以苏合丸与蛣蜣比喻反对。", "phases": [], "location_name": "后唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "44f4ee9b-6758-557e-8af3-4b7423f5fe33"}, {"title": "孔循安重诲持续誉崔协短李琪，冯道崔协同日拜相", "start_year": 927, "end_year": 927, "time_original": "927年正月癸亥", "dynasty": "五代十国", "description": "孔循安重诲持续誉崔协短李琪，冯道崔协同日拜相。", "phases": [], "location_name": "后唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "96ffd3cc-1458-51ab-824c-f78e965ec6c7"}, {"title": "王延禀返建州，王延钧相送；延禀以守先人基业警告，延钧逊谢而色变", "start_year": 927, "end_year": 927, "time_original": "927年正月戊辰", "dynasty": "五代十国", "description": "王延禀返建州，王延钧相送；延禀以守先人基业警告，延钧逊谢而色变。", "phases": [], "location_name": "闽、福州至建州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c290f9eb-cfb5-56e7-9d5a-d2a312ebca41"}, {"title": "后唐初令天下长吏每旬亲自引问审查在押囚犯", "start_year": 927, "end_year": 927, "time_original": "927年正月庚午", "dynasty": "五代十国", "description": "后唐初令天下长吏每旬亲自引问审查在押囚犯。", "phases": [], "location_name": "天下州府", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核